export function bindAdminBatch(ui,data){
 const root=ui.panel;ui.adminSelection??=new Set();const valid=new Set(data.players.filter(p=>p.id!==data.actorId).map(p=>p.id));for(const id of ui.adminSelection)if(!valid.has(id))ui.adminSelection.delete(id);
 const boxes=[...root.querySelectorAll('[data-select-player]:not(:disabled)')],all=root.querySelector('[data-select-all]'),input=root.querySelector('[data-batch-grant] input');input.value=ui.batchAmount??'2000';input.oninput=()=>ui.batchAmount=input.value;
 const update=()=>{for(const box of boxes){box.checked=ui.adminSelection.has(box.dataset.selectPlayer);box.closest('article').classList.toggle('is-selected',box.checked)}const count=ui.adminSelection.size;root.querySelector('[data-selected-count]').textContent='已选 '+count+' 人';all.checked=count>0&&count===boxes.length;all.indeterminate=count>0&&count<boxes.length;all.disabled=!boxes.length;root.querySelectorAll('[data-batch-action]').forEach(b=>b.disabled=!count||count>100);};
 for(const box of boxes)box.onchange=()=>{if(box.checked&&ui.adminSelection.size>=100){box.checked=false;ui.error(Error('每批最多选择 100 人'));return}if(box.checked)ui.adminSelection.add(box.dataset.selectPlayer);else ui.adminSelection.delete(box.dataset.selectPlayer);update()};
 all.onchange=()=>{ui.adminSelection.clear();if(all.checked)boxes.slice(0,100).forEach(b=>ui.adminSelection.add(b.dataset.selectPlayer));update()};root.querySelector('[data-select-clear]').onclick=()=>{ui.adminSelection.clear();update()};
 const submit=(action,button)=>{const ids=[...ui.adminSelection];if(!ids.length||ui.manageBusy)return;const request={kind:'batch',ids};let text='';if(action==='grant'){const amount=Number(input.value);if(!Number.isSafeInteger(amount)||amount<1||amount>10000000){ui.error(Error('请输入 1–10000000 的整数'));return}Object.assign(request,{action:'grant',amount});text=`给所选 ${ids.length} 位玩家每人发放 ${amount.toLocaleString()} 筹码，共 ${(amount*ids.length).toLocaleString()} 筹码？`}else if(action==='delete'){request.action='deletePlayer';text=`删除所选 ${ids.length} 位玩家的昵称、形象、权限和筹码？他们正在参与的牌局会关闭，其他玩家筹码会退回。删除后重新登记不会再次赠送筹码。`}else{Object.assign(request,{action:'permission',status:action==='allow'?'allowed':'blocked'});text=`${action==='allow'?'允许':'停用'}所选 ${ids.length} 位玩家的设备？`}if(confirm(text))ui.manage(request,button)};
 root.querySelector('[data-batch-grant]').onsubmit=e=>{e.preventDefault();submit('grant',root.querySelector('[data-batch-action="grant"]'))};root.querySelectorAll('[data-batch-action]:not([data-batch-action="grant"])').forEach(b=>b.onclick=()=>submit(b.dataset.batchAction,b));update();
}
